/*
 * Active-game autosave — persistent recovery draft for the game currently
 * in progress. Stored in localStorage (persists across page reloads caused
 * by macOS sleep, tab discard, or crash; not the HTTP cache) as a single
 * draft keyed by ACTIVE_GAME_STORAGE_KEY. Not a game history: a fresh game
 * intentionally replaces the draft (via clearActiveGame).
 *
 * Draft layout: the full SGF serialization of the game tree (variations
 * included) + the current navigation cursor as a child-index path from the
 * root (node ids are regenerated by the SGF parser, so paths are used
 * instead) + the game mode needed to resume play. All reads are defensive:
 * malformed or unsupported drafts yield null instead of throwing.
 */
import type { BoardSize, GameMode } from './types.ts'
import { createGameState } from './gameState.ts'
import type { GameState } from './gameState.ts'
import { getCursorPath, setCursorPath } from './gameTree.ts'
import type { GameTree, GameTreeNode } from './gameTree.ts'
import { getBoardSizeFromTree, sgfToTree, treeToSGF } from './sgfIo.ts'

export const ACTIVE_GAME_STORAGE_KEY = 'badukdojang-active-game'

/** Draft schema version — bump when the stored shape changes. */
const DRAFT_VERSION = 1

export interface ActiveGameDraft {
  version: 1
  /** Full SGF serialization of the game tree (variations preserved). */
  sgf: string
  /** Child-index path from root to the current navigation node. */
  cursorPath: number[]
  /** Game mode needed to continue play after restoration. */
  gameMode: GameMode
  savedAt: number
}

export interface ActiveGameSnapshot {
  boardSize: BoardSize
  gameMode: GameMode
}

/** Game restored from the recovery draft, ready for app startup. */
export interface RestoredGame extends ActiveGameSnapshot {
  gameState: GameState
}

/** Persist the current game as the single active recovery draft. */
export function saveActiveGame(
  tree: GameTree,
  { boardSize, gameMode }: ActiveGameSnapshot,
): void {
  try {
    const draft: ActiveGameDraft = {
      version: DRAFT_VERSION,
      sgf: treeToSGF(tree, boardSize),
      cursorPath: getCursorPath(tree),
      gameMode,
      savedAt: Date.now(),
    }
    localStorage.setItem(ACTIVE_GAME_STORAGE_KEY, JSON.stringify(draft))
  } catch {
    // Storage may be unavailable (private mode, quota) or the SGF may
    // refuse to serialize — never let saving break the game.
  }
}

/** Remove the active-game draft (starting a fresh game replaces it). */
export function clearActiveGame(): void {
  try {
    localStorage.removeItem(ACTIVE_GAME_STORAGE_KEY)
  } catch {
    // Storage unavailable — nothing to clear.
  }
}

/**
 * Read and validate the draft from localStorage, or null when absent,
 * malformed, or from an unsupported schema version. recoverable fields
 * (gameMode, cursorPath) fall back to safe defaults; only a missing or
 * unparsable sgf body rejects the whole draft.
 */
export function loadActiveGameDraft(): ActiveGameDraft | null {
  try {
    const raw = localStorage.getItem(ACTIVE_GAME_STORAGE_KEY)
    if (!raw) return null
    const value = JSON.parse(raw) as Partial<ActiveGameDraft> | null
    if (value === null || typeof value !== 'object') return null
    if (value.version !== DRAFT_VERSION) return null
    if (typeof value.sgf !== 'string' || value.sgf.trim() === '') return null
    const cursorPath = Array.isArray(value.cursorPath)
      ? value.cursorPath.filter(
          (index): index is number =>
            typeof index === 'number' && Number.isInteger(index) && index >= 0,
        )
      : []
    const gameMode: GameMode = value.gameMode === 'ai' ? 'ai' : 'selfplay'
    const savedAt = typeof value.savedAt === 'number' ? value.savedAt : 0
    return { version: DRAFT_VERSION, sgf: value.sgf, cursorPath, gameMode, savedAt }
  } catch {
    return null
  }
}

/**
 * Whether a node subtree holds any game content: a move/pass (B/W
 * properties, including empty ones = pass) or setup stones anywhere in
 * this node or its descendants.
 */
function subtreeHasGameContent(node: GameTreeNode): boolean {
  const data = node.data as {
    B?: unknown[]
    W?: unknown[]
    AB?: unknown[]
    AW?: unknown[]
  }
  if (data.B !== undefined || data.W !== undefined) return true
  if ((data.AB?.length ?? 0) > 0 || (data.AW?.length ?? 0) > 0) return true
  return node.children.some(subtreeHasGameContent)
}

/**
 * A game with no moves, passes, or setup stones anywhere in the whole
 * tree — i.e. the initial empty board. Whole-tree, not just the current
 * cursor path: a non-empty SGF navigated back to root must neither skip
 * autosave (losing the cursor update) nor skip discard confirmations.
 * Blank games are skipped by autosave so booting with nothing to restore
 * never overwrites a valid saved draft with the blank initial state.
 */
export function isBlankGame(tree: GameTree): boolean {
  return !subtreeHasGameContent(tree.root)
}

/**
 * Rebuild a playable game from the recovery draft. Returns null when the
 * draft is absent/malformed or its SGF fails to parse — callers must treat
 * that as "nothing to restore", not as an empty game.
 */
export function restoreActiveGame(): RestoredGame | null {
  const draft = loadActiveGameDraft()
  if (draft === null) return null
  try {
    const tree = sgfToTree(draft.sgf)
    const parsedSize = getBoardSizeFromTree(tree)
    const boardSize: BoardSize = [9, 13, 19].includes(parsedSize)
      ? (parsedSize as BoardSize)
      : 19
    // sgfToTree parked the cursor on the deepest first-child node; restore
    // the saved navigation position instead (clamped by setCursorPath).
    setCursorPath(tree, draft.cursorPath)
    return {
      gameState: createGameState(boardSize, tree),
      boardSize,
      gameMode: draft.gameMode,
    }
  } catch (error) {
    console.warn('활성 대국 복구에 실패했습니다:', error)
    return null
  }
}
